const PHOTOS={Kenji:"data:image/jpeg;base64,",Spike:"data:image/jpeg;base64,",Nori:"data:image/jpeg;base64,",Lumi:"data:image/jpeg;base64,",Shade:"data:image/jpeg;base64,"};
const svgOf=(k)=>`<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg"><defs><clipPath id="cp${k}"><circle cx="50" cy="50" r="45"/></clipPath></defs><circle cx="50" cy="50" r="48" fill="${SKINS[k].c}" stroke="#111" stroke-width="4"/><image href="${PHOTOS[k]}" x="5" y="5" width="90" height="90" preserveAspectRatio="xMidYMid slice" clip-path="url(#cp${k})"/><circle cx="50" cy="50" r="45" fill="none" stroke="#111" stroke-width="3"/></svg>`;
const $=id=>document.getElementById(id);
const show=id=>{document.querySelectorAll('.page').forEach(p=>p.classList.toggle('on',p.id===id));window.scrollTo(0,0)};

/* Sauvegarde (par brawler) */
let store={};try{store=JSON.parse(localStorage.getItem('lab')||'{}')}catch(e){}
const save=()=>{try{localStorage.setItem('lab',JSON.stringify(store))}catch(e){}};
let player={name:store.name||'',skin:store.skin||''};
const prog=()=>(store.prog=store.prog||{},store.prog[player.skin]=store.prog[player.skin]||[]);
const doneN=c=>prog().filter(i=>Math.floor(i/10)===c).length;
const unlocked=c=>c===0||doneN(c-1)>=10;

/* Page 1 */
const skinsEl=$('skins');
Object.keys(SKINS).forEach(k=>{
  const b=document.createElement('button');b.className='skin';b.dataset.k=k;b.innerHTML=svgOf(k)+k;
  b.onclick=()=>{player.skin=k;refresh1()};skinsEl.appendChild(b);
});
function refresh1(){
  player.name=$('name').value.trim();
  document.querySelectorAll('.skin').forEach(b=>b.classList.toggle('sel',b.dataset.k===player.skin));
  $('nextBtn').style.display=(player.name&&player.skin)?'inline-block':'none';
}
$('name').value=player.name;$('name').oninput=refresh1;refresh1();
$('nextBtn').onclick=()=>{store.name=player.name;store.skin=player.skin;save();buildLevels();show('p2')};

/* Page 2 */
function buildLevels(){
  const root=$('cats');root.innerHTML='';
  CATS.forEach((n,c)=>{
    const ok=unlocked(c),d=doneN(c),el=document.createElement('div');
    el.className='cat'+(ok?'':' locked');
    el.innerHTML=`<header><span style="color:${CCOL[c]};-webkit-text-stroke:1.5px #111;paint-order:stroke fill;font-size:1.6rem">${ok?'':'🔒 '}${n}</span><span class="cnt">${d}/10</span></header>`;
    const g=document.createElement('div');g.className='lvls';
    for(let i=0;i<10;i++){
      const id=c*10+i,b=document.createElement('button');
      b.className='lvl '+(prog().includes(id)?'done':ok?'open':'');b.textContent=i+1;b.disabled=!ok;
      b.setAttribute('aria-label',`${n} niveau ${i+1}`);b.onclick=()=>startLevel(id);g.appendChild(b);
    }
    el.appendChild(g);root.appendChild(el);
  });
}
$('back').onclick=()=>{refresh1();show('p1')};

/* Page 3 : labyrinthe */
const cv=$('cv'),ctx=cv.getContext('2d');
let W,H,cell,grid,pos,goal,lvl,imgP,busy=false;
function gen(w,h){
  const g=Array.from({length:h},()=>Array.from({length:w},()=>[1,1,1,1])); // haut,droite,bas,gauche = murs
  const seen=Array.from({length:h},()=>Array(w).fill(false)),st=[[0,0]];seen[0][0]=true;
  const dx=[0,1,0,-1],dy=[-1,0,1,0];
  while(st.length){
    const [x,y]=st[st.length-1],opts=[];
    for(let d=0;d<4;d++){const nx=x+dx[d],ny=y+dy[d];if(nx>=0&&ny>=0&&nx<w&&ny<h&&!seen[ny][nx])opts.push(d)}
    if(!opts.length){st.pop();continue}
    const d=opts[Math.floor(Math.random()*opts.length)],nx=x+dx[d],ny=y+dy[d];
    g[y][x][d]=0;g[ny][nx][(d+2)%4]=0;seen[ny][nx]=true;st.push([nx,ny]);
  }
  return g;
}
function startLevel(id){
  lvl=id;const t=id/79;                       // 0 = très facile, 1 = très dur
  W=Math.round(5+t*25);H=Math.round(5+t*25);
  grid=gen(W,H);pos=[0,0];goal=[W-1,H-1];
  imgP=new Image();imgP.onload=draw;
  imgP.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svgOf(player.skin));
  $('top').innerHTML=`<b>${player.name}</b> · ${CATS[Math.floor(id/10)]} – niveau ${id%10+1}`;
  show('p3');fit();busy=false;
}
function fit(){
  if(!grid)return;
  const side=Math.min(window.innerWidth-40,720,window.innerHeight-300);
  cell=Math.max(10,Math.floor(Math.max(side,200)/Math.max(W,H)));
  cv.width=cell*W;cv.height=cell*H;draw();
}
function draw(){
  if(!grid)return;
  ctx.clearRect(0,0,cv.width,cv.height);
  ctx.fillStyle='#c9f2cf';ctx.fillRect(0,0,cell,cell);
  ctx.fillStyle='#ffb3ad';ctx.fillRect(goal[0]*cell,goal[1]*cell,cell,cell);
  ctx.strokeStyle='#1a1209';ctx.lineWidth=Math.max(2,cell/9);ctx.lineCap='round';ctx.beginPath();
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){
    const w=grid[y][x],X=x*cell,Y=y*cell;
    if(w[0]){ctx.moveTo(X,Y);ctx.lineTo(X+cell,Y)}
    if(w[1]){ctx.moveTo(X+cell,Y);ctx.lineTo(X+cell,Y+cell)}
    if(w[2]){ctx.moveTo(X,Y+cell);ctx.lineTo(X+cell,Y+cell)}
    if(w[3]){ctx.moveTo(X,Y);ctx.lineTo(X,Y+cell)}
  }
  ctx.stroke();
  // arrivée : drapeau
  const gx=goal[0]*cell,gy=goal[1]*cell;
  ctx.fillStyle='#e8332a';ctx.font=`${cell*.7}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillText('🏁',gx+cell/2,gy+cell/2);
  if(imgP&&imgP.complete)ctx.drawImage(imgP,pos[0]*cell+cell*.1,pos[1]*cell+cell*.1,cell*.8,cell*.8);
}
function move(d){
  if(busy||!grid)return;
  const [x,y]=pos;if(grid[y][x][d])return;
  pos=[x+[0,1,0,-1][d],y+[-1,0,1,0][d]];draw();
  if(pos[0]===goal[0]&&pos[1]===goal[1])win();
}
document.querySelectorAll('.pad button').forEach(b=>{
  let t;const d=+b.dataset.d;
  const stop=()=>{clearInterval(t)};
  b.addEventListener('pointerdown',e=>{e.preventDefault();move(d);stop();t=setInterval(()=>move(d),130)});
  ['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,stop));
});
addEventListener('keydown',e=>{
  if(!$('p3').classList.contains('on'))return;
  const m={ArrowUp:0,ArrowRight:1,ArrowDown:2,ArrowLeft:3,w:0,d:1,s:2,a:3}[e.key];
  if(m!==undefined){e.preventDefault();move(m)}
});
addEventListener('resize',fit);

/* Victoire + son d'achievement */
function chime(){
  try{
    const A=new (window.AudioContext||window.webkitAudioContext)(),t=A.currentTime;
    [523.25,659.25,783.99,1046.5,1318.5].forEach((f,i)=>{
      const o=A.createOscillator(),g=A.createGain();o.type='triangle';o.frequency.value=f;
      g.gain.setValueAtTime(0,t+i*.11);g.gain.linearRampToValueAtTime(.3,t+i*.11+.02);g.gain.exponentialRampToValueAtTime(.001,t+i*.11+.5);
      o.connect(g).connect(A.destination);o.start(t+i*.11);o.stop(t+i*.11+.55);
    });
  }catch(e){}
}
function win(){
  busy=true;const p=prog();if(!p.includes(lvl)){p.push(lvl);save()}
  const last=lvl>=79,c=Math.floor(lvl/10);
  $('winTxt').textContent=last?`${player.name}, tu as terminé tous les niveaux !`:
    (lvl%10===9?`Catégorie ${CATS[c]} terminée ! ${CATS[c+1]} est débloquée.`:`Niveau ${lvl%10+1} réussi, ${player.name} !`);
  $('nextLvl').style.display=last?'none':'inline-block';
  $('win').classList.add('on');chime();
}
$('nextLvl').onclick=()=>{$('win').classList.remove('on');startLevel(lvl+1)};
const quit=()=>{$('win').classList.remove('on');grid=null;buildLevels();show('p2')};
$('quitWin').onclick=quit;$('quitGame').onclick=quit;
